export const WRITEUPS = {"levelup": {"slug": "levelup", "name": "LevelUp", "floor": "engineering", "onSite": true, "order": 0, "template": "engineering", "status": "approved", "oneLiner": "A clip-on bubble level for barbells, built to improve your gym performances with leveled exercises.", "context": {"course": "DSGN 308 · Human-Centered Product Design", "when": "Spring 2025", "team": "Team of 7", "partner": "Segal Design Institute", "role": "Design researcher & CAD — problem finding, concept sketching, clip modelling, business model"}, "software": ["slides", "solidworks"], "skills": [{"name": "Observational research (AEIOU)", "evidence": "problem"}, {"name": "User interviews", "evidence": "problem"}, {"name": "Competitive analysis", "evidence": "problem"}, {"name": "Design criteria & decision matrices", "evidence": "problem"}, {"name": "Brainwriting", "evidence": "brainstorm"}, {"name": "Sketching", "evidence": "brainstorm"}, {"name": "Business model", "evidence": "next"}, {"name": "3D printing (FDM)", "evidence": "final"}, {"name": "CAD modelling", "evidence": "final"}], "classes": ["dsgn308"], "cover": "assets/projects/levelup.webp", "blocks": [{"id": "problem", "stage": "problem", "title": "Grocery bags or barbell?", "text": "DSGN 308 makes us identify a personal problem in our daily life expriences and solve it by developing a physical product. Our seven-person team pooled a 55-response survey, AEIOU sessions and our own complaints into 122 opportunities, kept the 44 a product could fix, and chased three: a messy machine shop, slipping grocery-bag straps, and the gym.\n\nWhile I led the grocery space, I tested our initial assumption through a 20-person survey, 10 user interviews, and a competitive analysis of eight existing solutions. The data weakened our original hypothesis: slipping straps ranked sixth out of seven grocery frustrations, averaged only 2.8/5 in severity, and was never independently mentioned by any of our interviewees. Meanwhile, the gym team combined observations, interviews, and timed trials: they saw 3 of 5 bench press users lifting unevenly within a 20-minute observation and measured an average 4.5-minute wait for occupied cardio machines. After comparing the two gym problems across five criteria, uneven barbell lifting narrowly won, and our final weighted matrix—impact, feasibility, team interest, novelty, and market size—put the gym first at 82.5, ahead of the shop at 70.5 and groceries at 63, which prompted us to eventually move forward with the gym space opportunity.", "layout": "gallery", "media": [{"src": "assets/projects/levelup/grocery.webp", "caption": "", "kind": "photo"}]}, {"id": "research", "stage": "research", "title": "Commonly overlooked", "text": "Two teammates spent an hour at SPAC, the campus gym: 30 minutes of AEIOU observation, then five interviews. Barbells were the busiest equipment, spotters were rare, and in 20 minutes three people lifted a visibly uneven bar. Most interviewees didn't see it as their problem, including one we had just watched do it.\n\nA Northwestern lift coach said mild upper-body imbalance is usually fine, but in extreme cases a raised shoulder can lead to impingement, rotator-cuff trouble and, at worst, a torn labrum. The fixes on offer ran from a $274.99 barbell with a built-in level to a $3,999 smart gym, or another person watching you.", "layout": "text-media", "media": [{"src": "assets/projects/levelup/benchmark-existing-fixes.webp", "caption": "Our benchmark of seven existing fixes, +1/0/−1 on cost, access, effectiveness, convenience and safety. Most cost money or need another person; dumbbells only help up to a point.", "kind": "chart"}]}, {"id": "quote", "stage": "research", "title": "Everyone sees it — in someone else", "text": "“I don't personally have problems with it because I have good body control. I notice it in other people though.” — a gym-goer at SPAC, whom we had just watched bench unevenly", "layout": "quote", "media": []}, {"id": "needs", "stage": "needs", "title": "Every need needs a number!", "text": "Our first spec sheet asked for “fits in pocket” and “universally understandable”; by the final report every need had a number. The final prototype, tested with three lifters at SPAC on June 10:\n\n! Need | Spec | LevelUp\nVisible | Testers rate how well they saw it: ≥ 4/5 | 4.35/5\nIntuitive | On the bar without instructions in < 5 s | 2.5 s average\nUnobstructive | Never touches the lifter | Hit 1 of 3 chests: miss\nPortable | Fits an average gym bag | 2.76 × 1.34 × 1.21 in\nAdaptable | 2+ exercises | 4 (we simulated them): bench, spotted squat, row, curl\nAdaptable | Fits 28.5 mm bars ± 3 mm | 28.5 mm only: miss\nCost-effective | Unit cost < $10 | $1.30 or $3.90 (our figures differ): pass\nBalance-effective | ≥ 90% of reps level | 100% (60% with the vial hidden)\nIntentional | Each rep slows by > 1 s | 0.98 s: a miss the report rounded up", "layout": "facts", "media": []}, {"id": "brainstorm", "stage": "brainstorm", "title": "The obvious idea showed up six times", "text": "We brainwrote alone first, ten ideas each, so no single voice set the direction: 70 ideas, then three sketches apiece, 21 in all. Lasers, accelerometers, phone apps and wearables all appeared, but six of our seven lists had a bubble level on them.\n\nMine had three, plus three ideas for marking where your hands go. I sketched a level vial capped with magnets, to stick straight onto a steel bar; magnets turned up on two other lists too, and the sketch made our final deck. We took three directions into mockups: a plain level, a phone running a level app, and a bearing that slides when the bar tips.", "layout": "gallery", "media": [{"src": "assets/projects/levelup/sketch-magnetic-level-kay.webp", "caption": "My sketch for the May 11 concept round: a level vial capped with magnets.", "kind": "sketch"}, {"src": "assets/projects/levelup/sketch-phone-on-bar.webp", "caption": "A teammate's sketch: the phone as the level, clipped to the bar.", "kind": "sketch"}, {"src": "assets/projects/levelup/sketch-bearing-clips.webp", "caption": "A teammate's sketch: bearing cuffs that slide into your hand when the bar tips.", "kind": "sketch"}]}, {"id": "prototype", "stage": "prototype", "title": "Three mockups ", "text": "We built cheap: cardboard, velcro, zip ties and a $5.99 five-pack of magnetic levels. The first two rounds (May 21–22) only tested how a level holds on. Magnets won; the shaft collars took too long, the velcro nearly hit a chin, and the magnetic tape we ordered wouldn't stick to the gym's bars.\n\nThen we pitted three directions against each other. The lift coach preferred the bearing, our class the phone, gym-goers the plain level. We chose the level on our requirements: most intuitive, portable, cheapest and buildable in the time left. Its flaw came with it: a small bubble that rolls out of view as the bar turns.", "layout": "gallery", "media": [{"src": "assets/projects/levelup/mockup-r1-velcro.webp", "caption": "Round 1 (May 21), velcro on cardboard: easy on, but the straps nearly hit a tester's chin.", "kind": "mockup"}, {"src": "assets/projects/levelup/mockup-r2-c-clip.webp", "caption": "Round 2's 1-inch clip was the fastest on, but too big for the gym's bars, so it spun. The clip came back at the end.", "kind": "mockup"}, {"src": "assets/projects/levelup/mockup-phone-stand.webp", "caption": "The phone stand: the most responsive readout, until its magnets let go and the phone fell as a tester lowered the bar.", "kind": "mockup"}, {"src": "assets/projects/levelup/test-bubble-vs-bearing.webp", "caption": "Bubble (left) against bearing (right): the bearing only started sliding after 0.7–2.7° of tilt, the bubble at once.", "kind": "test"}, {"src": "assets/projects/levelup/test-split-bubble.webp", "caption": "Lift-coach session: the bar met the coach's chest and the bubble split into several. Which one is level?", "kind": "test"}, {"src": "assets/projects/levelup/prototype-v1-two-levels.webp", "caption": "Final concept v1 (June 10): two levels on fabric, so one is always in view. The fabric let them twist out of line, and testers watched only one.", "kind": "prototype"}]}, {"id": "final", "stage": "final", "title": "The losing mockup gave the winner its angle", "text": "We rebuilt the level from scratch; I helped model the clip in CAD and print it. LevelUp is a printed black PLA clip that snaps over the bar, with no straps or magnets, and a 1-inch vial press-fit on an arm standing just under an inch off the bar. That angle came from the phone stand we had dropped: testers kept tilting the phone forward to face them.\n\nOn June 10, three SPAC lifters clipped it on without instructions in 2.5 seconds on average. With the vial hidden, the bubble left the level zone nine times over their reps; in view, never. It also hit one tester's chest and fits only one bar size.", "layout": "text-media", "media": [{"src": "assets/projects/levelup/levelup-product.webp", "caption": "LevelUp: a compliant PLA clip, and a 1-inch vial press-fit on a 90° arm.", "kind": "prototype"}, {"src": "assets/projects/levelup/levelup-lifter-view.webp", "caption": "What the lifter sees during a barbell row: the vial between the hands.", "kind": "test"}]}, {"id": "next", "stage": "next", "title": "Million Dollar Vision", "text": "I built our business model canvas: beginner lifters buying direct; rec centres, gyms and trainers buying wholesale; a keychain level as a side line (my first brainstorm idea, back again). We priced it at $9.99 retail, $7.99 wholesale. Reading the canvas now, it still pitches a “magnetic clip-on”, and our cost table prices a magnet-and-rubber build at $3.90 a unit. The part we tested was printed plastic and a vial. Next time I'd cost the object on the bench.\n\nFor future iterations, we would choose a clip for 25.5–31.5 mm bars, a shape that clears the chest, rubber for grip, and a thicker fluid for experienced lifters.", "layout": "text-media", "media": [{"src": "assets/projects/levelup/business-model-canvas.webp", "caption": "My business model canvas for LevelUp, June 2025.", "kind": "diagram"}]}]}, "notipclip": {"slug": "notipclip", "name": "No-Tip-Clip", "floor": "engineering", "onSite": true, "order": 1, "template": "engineering", "status": "approved", "oneLiner": "A 3D-printed clamp and caster that works like a training wheel for back-heavy halo-traction wheelchairs.", "context": {"course": "DSGN 106-2 · Design Thinking & Communication 2", "when": "Spring 2024", "team": "Team of 4", "partner": "Shriners Children's Chicago", "role": "User researcher & technical writer — interviews, mockup testing, SolidWorks modelling, documentation"}, "software": ["solidworks", "cura"], "skills": [{"name": "User interviews", "evidence": "research"}, {"name": "Client communication", "evidence": "research"}, {"name": "Sketching", "evidence": "brainstorm"}, {"name": "Low-fi mockups", "evidence": "prototype"}, {"name": "Proxy-user testing", "evidence": "prototype"}, {"name": "Technical writing", "evidence": "final"}, {"name": "Risk assessment", "evidence": "next"}, {"name": "CAD modelling", "evidence": "final"}, {"name": "3D printing (FDM)", "evidence": "final"}], "classes": ["dsgn106-2"], "cover": "assets/projects/notipclip.webp", "blocks": [{"id": "problem", "stage": "problem", "title": "When the chair tips, the pull goes sideways", "text": "Shriners Children's Chicago prepares children with severe scoliosis and kyphosis for spinal fusion with halo traction: a ring pinned to the skull, a rope over a boom on the back of a walker or wheelchair, and weights that slowly stretch the spine. The boom makes the wheelchair back-heavy, and a child is often too light to hold it down. When the chair tips, the weights sway and pull diagonally instead of straight up. Our partner, a clinician there, listed six problems with the equipment. We took this one, with ten weeks and a $150 class budget.", "layout": "text-media", "media": [{"src": "assets/projects/notipclip/traction-wheelchair-back.webp", "caption": "A traction wheelchair at Shriners Children's Chicago, from behind: the boom rises from the backrest and the traction rope runs down the back. Site visit, April 2024.", "kind": "photo"}]}, {"id": "research", "stage": "research", "title": "The current fix: sandbags that slip", "text": "We started with secondary research on halo traction. I set up our partner interview and site visit by email, wrote the interview guide, and was its lead interviewer on the Zoom call. On April 11 three of us visited the hospital; no patients were there, so we measured, photographed and handled the equipment. The hospital's fix for tipping is weight: cuff weights and sandbags velcroed or taped to the frame, 8–10 lb for a child. They slip, and they get in the way of the front wheels. We also learned that the clamps holding the traction frame on are no longer made.", "layout": "text-media", "media": [{"src": "assets/projects/notipclip/cuff-weight-fix.webp", "caption": "The hospital's fix: a cuff weight strapped to the frame with Velcro.", "kind": "photo"}, {"src": "assets/projects/notipclip/worn-circular-clamp.webp", "caption": "A worn circular clamp, measured on site. Its supplier no longer makes it.", "kind": "photo"}]}, {"id": "needs", "stage": "needs", "title": "From improving everything to one clamp", "text": "Our first mission statement promised a safer, more durable device overall. Three revisions later it named one part: a modular clamp with an adjustable nut-and-bolt height. Every spec but the budget came from our partner.\n\n!Need | Spec\nStops tipping | The wheelchair does not tip\nDetachable | Clips on and off\nQuick | Under 5 minutes to set up\nLight | Under 3 lb\nDurable | Takes rough use without losing effect\nAffordable | Under $150 (class budget)\n\nWe would judge the mockups on size, weight, safety, effectiveness and modularity.", "layout": "facts", "media": []}, {"id": "brainstorm", "stage": "brainstorm", "title": "Our first instinct: fight weight with weight", "text": "Each of us took three needs and sketched ten ideas for each. My thirty ran from a rubber lining for the slipping clamps to gym-style pin holes for height, plus ten answers to the weight imbalance, seven of them adding or moving weight. We pooled our lists, ranked our top fives in private and agreed on eight ideas. Our first matrix compared only weight concepts; the professors asked for broader options, checked against duration, stability and feasibility. I then drew mockup plans for three concepts: a training wheel, an adjustable weight bag and a weight-balance calculator.", "layout": "gallery", "media": [{"src": "assets/projects/notipclip/kay-ideas-weight.webp", "caption": "My ten ideas for the weight imbalance. Seven add or move weight.", "kind": "sketch"}, {"src": "assets/projects/notipclip/kay-ideas-clamp.webp", "caption": "My ten ideas for clamps that wear out and slide, starting with a rubber friction lining.", "kind": "sketch"}, {"src": "assets/projects/notipclip/mockup-plan-training-wheel.webp", "caption": "Mockup plan, April 25: three places a training wheel could attach.", "kind": "sketch"}, {"src": "assets/projects/notipclip/mockup-plan-weight-bag.webp", "caption": "Mockup plan: where adjustable weights could sit under the seat.", "kind": "sketch"}]}, {"id": "prototype", "stage": "prototype", "title": "Past five kilos, the bag stopped helping", "text": "In May we tested two mockups in the Segal Prototyping Lab and outdoors, as proxy users; the calculator never left paper. I helped rig the weight bag under the chair, against a 7 kg hanging weight, and wrote the report.\n\n!Weight bag | 1 kg | 3 kg | 5 kg | 10 kg\nStability | 2/10 | 5/10 | 8/10 | 8/10\nFlexibility | 5/10 | 7/10 | 6/10 | 4/10\n\nPast 5 kg, extra weight bought no stability and cost flexibility, and the bag was hard to place the same way twice. The wheel steadied the chair and promised one size for all. We decided to move forward with that.", "layout": "facts", "media": [{"src": "assets/projects/notipclip/training-wheel-mockup.webp", "caption": "The training-wheel mockup held to the back of a wheelchair. Its row of holes set the height, and left thin metal between them.", "kind": "mockup"}]}, {"id": "quote", "stage": "", "title": "", "text": "Instead of adding weight, we added a point of contact with the floor.", "layout": "quote", "media": []}, {"id": "final", "stage": "final", "title": "A $62 training wheel that clamps on", "text": "The No-Tip-Clip is a two-piece clamp that I helped model in SolidWorks, printed at 95% infill in about 50 hours. It bolts around the wheelchair's lowest rear rod; an oval hole about 1.5 times the radius of standard frame tubing lets one clamp grip different frames. A ⅞-inch bolt through its side carries a caster: turn it until the wheel just touches the floor, then lock two nuts. Although we planned to weld the bolt to the caster, for technical limitations, we used a band-sawn polycarbonate plate to join them instead. The costs for those parts came with a total of $62.26, which was well within our $150 budget.", "layout": "gallery", "media": [{"src": "assets/projects/notipclip/cad-render.webp", "caption": "The final design in CAD: printed clamp, ⅞-inch bolt, caster.", "kind": "cad"}, {"src": "assets/projects/notipclip/installed.webp", "caption": "The prototype on the lowest rear rod of a wheelchair, wheel just touching the floor.", "kind": "prototype"}, {"src": "assets/projects/notipclip/setting-height.webp", "caption": "Setting the height: turn the wheel on the bolt, then lock the nuts. From the instructions for use.", "kind": "prototype"}]}, {"id": "next", "stage": "next", "title": "Next version: no tools, no tilt", "text": "Our closing slide ticked three of four requirements; fitting different equipment stayed unticked. On a sloped rod the wheel leans, so angle and attachment top our next steps, with Velcro clips, an improved wheel, and metal or a weld in place of the plastic plate. The safety evaluation we drafted ranked vibration through the clamp as the top risk, so add damping, plus the load test we promised at the design review. ", "layout": "text-media", "media": [{"src": "assets/projects/notipclip/sloped-rod-tilt.webp", "caption": "On a sloped rod the wheel leans. The angle is the next problem to solve.", "kind": "prototype"}]}]}, "slidemaster": {"slug": "slidemaster", "name": "Slide Master", "floor": "engineering", "onSite": true, "order": 2, "template": "engineering", "status": "approved", "oneLiner": "A wheelchair-to-shower transfer board that uses sliding mechanism to prevent skin injury in patients.", "context": {"course": "DSGN 106-1 · Design Thinking & Communication 1", "when": "Winter 2024", "team": "Team of 4", "partner": "Occupational therapist, spinal-cord-injury rehabilitation", "role": "Mockup & documentation lead — mockup plans, CAD and drawings, design freeze, concept rationale"}, "software": ["tinkercad", "onshape"], "skills": [{"name": "Competitive analysis", "evidence": "research"}, {"name": "User interviews", "evidence": "research"}, {"name": "User needs → specs", "evidence": "needs"}, {"name": "Sketching", "evidence": "brainstorm"}, {"name": "Low-fi mockups", "evidence": "brainstorm"}, {"name": "Engineering drawings", "evidence": "prototype"}, {"name": "Posters & presentations", "evidence": "final"}, {"name": "Technical writing", "evidence": "final"}, {"name": "CAD modelling", "evidence": "prototype"}], "classes": ["dsgn106-1"], "cover": "assets/projects/slidemaster.webp", "blocks": [{"id": "problem", "stage": "problem", "title": "Damage the user can't feel", "text": "An occupational therapist who helps people with spinal-cord injuries manage daily tasks like bathing brought our DTC team a problem. Her patients cross from wheelchair to shower chair on a transfer board, usually a flat plank with two hand holes, scooting across it on bare, often wet skin they cannot feel. So friction damage goes unnoticed. Boards also slip off the tub ledge, are hard to get onto, and pinch fingers. A patient who can't transfer safely is left with bed baths. Since the boards are paid for by insurance, we were asked to keep our budget around $60.", "layout": "text-media", "media": [{"src": "assets/projects/slidemaster/scenario-storyboard.webp", "caption": "Scenario breakdown from our first research deck: wheelchair beside the tub, board across the gap, patient on the shower chair.", "kind": "sketch"}]}, {"id": "research", "stage": "research", "title": "The obvious fix already existed", "text": "We began with what's on the market: the plain wooden board, a tub transfer bench, the ShowerGlyde sliding system, ceiling lifts and the $249 BeasyGlyder. Our partner filled in the rest on a video call, where I was one of the note-takers. The surprise came on our week-5 visit to her unit. Sliding boards already existed, and staff rarely used them: they add instability, and their seats are narrower than the board, so skin hangs over the edge, drags and gets caught in the mechanism. Nobody there liked curved boards either. We weren't short of ideas, yet each existing one failed somewhere specific.", "layout": "text", "media": []}, {"id": "research-quote", "stage": "research", "title": "The rule we'd end up breaking", "text": "“Less material you have to get under your butt, the easier.” — our partner", "layout": "quote", "media": []}, {"id": "needs", "stage": "needs", "title": "Quantified Needs", "text": "Our first project definition turned the interview into requirements; three weeks later we wrote the second version with extra inputs we got from the site visit.\n\n! Requirement | First definition (Jan 23) | Second definition (Feb 14)\nFriction | not so slippery the user falls, not so rough it hurts skin | unchanged\nStability | no fear of falling; a handle if the board shifts | unchanged\nLoad | holds 500 lb | holds 200 lb\nLength | 3 ft at most | 3 ft at most\nWater | survives frequent contact | unchanged\nCleaning | antiseptic | dropped\nCost | $60 at most | $55 at most", "layout": "facts", "media": []}, {"id": "brainstorm", "stage": "brainstorm", "title": "We broke our own moving-parts rule", "text": "We each filled a row of an alternatives matrix. Mine asked for a slick, skin-friendly top over a metal structure “that allows the sliding to happen”, with rubber underneath; teammates added a tapered edge, a grab hole, a silk cover and rubber ends. I led the mockup plan: four tests on a standard board (silk cover, hollow handles, rubber bottom, slanted side), each tried with and without. After the site visit we split over two new options. Our instructors liked the dissent and reminded us DTC is a design class, not a prototype class. We chose the sliding seat, though our own constraints said “as little moving parts as possible”.", "layout": "gallery", "media": [{"src": "assets/projects/slidemaster/mockup-plan-combined-sketch.webp", "caption": "“A sketch of our design” from the mockup plan (Jan 25, 2024): slanted side, silk transfer surface, hollow handles, rubber bottom.", "kind": "sketch"}, {"src": "assets/projects/slidemaster/mockup-plan-pillowcase.webp", "caption": "Mockup 1: a silk “pillowcase” pulled over a standard board.", "kind": "sketch"}, {"src": "assets/projects/slidemaster/mockup-plan-hollow-handles.webp", "caption": "Mockup 2: hollow handles at both ends for a better grip.", "kind": "sketch"}, {"src": "assets/projects/slidemaster/mockup-plan-rubber-bottom.webp", "caption": "Mockup 3: rubber on the underside, maybe the two ends too, to grip the chair and the tub.", "kind": "sketch"}, {"src": "assets/projects/slidemaster/mockup-plan-slanted-side.webp", "caption": "Mockup 4: a slanted end to scoop under the patient.", "kind": "sketch"}]}, {"id": "prototype", "stage": "prototype", "title": "Failures and Iterations", "text": "We cut the first base from plywood and sanded its offcuts to 10°, 20° and 30° tapers, measured from the bottom and from the middle, then tested them for impact and tension; 10° from the bottom won. On February 13 a teammate tried a wheelchair-to-shower-chair transfer on the board. He never put his full weight down: the plywood began to fracture. We moved to solid wood, sat on the candidates ourselves and settled on pine. I helped build our Tinkercad model and draw the orthographic views, and at the design review three days later I presented the designs we had dropped and why. Reviewers asked for a much wider seat and softer edges; afterwards we traded wheels in rails for ball-bearing drawer slides.", "layout": "gallery", "media": [{"src": "assets/projects/slidemaster/tinkercad-early-model.webp", "caption": "Early Tinkercad model: hollow centre, rails for wheels, a sloped edge, a seat on top.", "kind": "cad"}, {"src": "assets/projects/slidemaster/design-review-old-design.webp", "caption": "My drawing of an earlier 30 × 10-inch version in top, front and side views, from my design-review slide.", "kind": "sketch"}, {"src": "assets/projects/slidemaster/design-review-sketch.webp", "caption": "The board as we showed it at the design review (Feb 16, 2024): slanted end, hollow centre, a seat on rails.", "kind": "sketch"}, {"src": "assets/projects/slidemaster/design-freeze-dimensions.webp", "caption": "Dimension drawing from the design-freeze package: 29 × 9-inch base, 23 × 3-inch cavity, 10 × 11-inch seat, 9 × 4-inch rubber end.", "kind": "sketch"}]}, {"id": "final", "stage": "final", "title": "The seat slides so the skin doesn't", "text": "Slide Master is a 29 × 9 × ¾-inch pine board; a 23 × 3-inch cavity cuts weight and doubles as a handle. A tapered end slips under the thigh, and rubber under the other end grips the tub. Two 12-inch ball-bearing drawer slides carry a cutting-board seat that covers them, so skin rides on the seat instead of dragging or pinching. We conducted the demo with students and faculty at the Segal Design Institute, along with our project partners, on March 9. Participants sat on the device and experienced the transfer process firsthand. We were pleased to see that the system worked successfully across users of different ages, genders, body sizes, and weights.\n", "layout": "text-media", "media": [{"src": "assets/projects/slidemaster/final-board-test-setup.webp", "caption": "The finished board between a shower chair and a wheelchair, in the test corner we set up at the Ford Design Center.", "kind": "photo"}, {"src": "assets/projects/slidemaster/exploded-view.webp", "caption": "The exploded view I drew for our poster: seat, slides, hollowed base, tapered end, rubber strip.", "kind": "sketch"}]}, {"id": "next", "stage": "next", "title": "Next: thinner, cheaper, easier to clean", "text": "Our report's list for the next version starts with testing by the people it's for and bringing the height down. It also proposes a different mechanism: a slide rail running in a U-channel cut into the board, which would hide the moving parts, give the seat a natural mount and reduce the pinch point that manufacturing errors could create. ", "layout": "text", "media": []}]}};
